            "เช็ดปลายกับ **ฟองน้ำชุบน้ำหมาด ๆ** (ไม่แฉะ) หรือ **ฝอยทองเหลือง** ก่อนบัดกรีแต่ละจุดหรือทุกไม่กี่จุด",
