            "ปลายดำ ตะกั่วไม่เกาะ: เช็ดด้วยฝอยทองเหลือง แล้วจุ่มลงครีมฟื้นปลาย (tip tinner/activator) ไล้ตะกั่วใหม่ ถ้ายังไม่หายหรือเห็นเนื้อทองแดงกร่อนเป็นหลุม ให้เปลี่ยนปลาย",
