          alt: "แถวบน ที่ดูดตะกั่ว 4 ขั้น 1 ง้างสปริงโดยกดก้านลูกสูบลง 2 ใช้หัวแร้งหลอมรอยต่อ 3 จ่อหัวดูดชิดรอยต่อขณะหัวแร้งยังแตะ 4 กดปุ่มปลด ลูกสูบดีดขึ้นดูดตะกั่วออก เหลือ pad กับขาเปล่า แถวล่าง สายถักซับตะกั่ว 3 ขั้น 1 วางสายถักทองแดงบนรอยต่อ 2 กดปลายหัวแร้งบนสายถัก ตะกั่วถูกดูดเข้าเส้นถักเปลี่ยนเป็นสีเงิน 3 ยกสายถักและหัวแร้งออกพร้อมกัน เหลือ pad สะอาด",
          wide: true,
