            "ใช้หัวแร้งหลอมรอยต่อให้เหลวทั่ว ถ้าตะกั่วเก่าหลอมยาก **เติมตะกั่วใหม่เล็กน้อย** ฟลักซ์ใหม่ช่วยให้หลอมเร็วขึ้น",
